CREATE SET TABLE MDP01_META.META_ETL_TEST ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      test_id INTEGER NOT NULL,      test_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      etl_job_id INTEGER,      table_id INTEGER,      column_id INTEGER,      test_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      test_sql VARCHAR(4000) CHARACTER SET LATIN NOT CASESPECIFIC,      accepted_values VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      ref_table_id INTEGER,      ref_column_id INTEGER,      warn_threshold DECIMAL(18,3),      error_threshold DECIMAL(18,3),      is_active CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      severity VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'ERROR',      beschreibung VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( test_id )UNIQUE INDEX ( test_name );